//! Offline Ground-Truth Reference Oracle Tests.
//! Validates combinatorics, Riemann tensor canonicalization, and transform values
//! against static fixtures generated by `scripts/gen_reference_fixtures.py`.

use algebra_engine::combinatorics::{bell_number, stirling_second_kind};
use cat_numbers::butler_portugal::{ButlerPortugal, TensorSymmetryN};
use serde::Deserialize;

#[derive(Deserialize)]
struct StirlingEntry {
    n: usize,
    k: usize,
    value: u64,
}

#[derive(Deserialize)]
struct BellEntry {
    n: usize,
    value: u64,
}

#[derive(Deserialize)]
struct RiemannOracle {
    name: String,
    perm: Vec<usize>,
    expected_canonical: Vec<usize>,
    expected_sign: i8,
}

#[derive(Deserialize)]
struct TransformOracle {
    kind: String,
    s_sample: Option<f64>,
    z_sample: Option<f64>,
    omega_sample: Option<f64>,
    expected_value: f64,
}

#[derive(Deserialize)]
struct ReferenceOracles {
    schema_version: u32,
    lyndon_ab_len4: Vec<String>,
    stirling_second_kind: Vec<StirlingEntry>,
    bell_numbers: Vec<BellEntry>,
    riemann_contractions: Vec<RiemannOracle>,
    transforms: Vec<TransformOracle>,
}

#[test]
fn test_offline_reference_oracles() {
    let raw = include_str!("../../fixtures/reference_oracles.json");
    let oracles: ReferenceOracles =
        serde_json::from_str(raw).expect("valid reference_oracles.json");
    assert_eq!(oracles.schema_version, 1);

    // 1. Lyndon words over {a, b} up to length 4: count = 2 + 1 + 2 + 3 = 8
    assert_eq!(oracles.lyndon_ab_len4.len(), 8);
    assert_eq!(oracles.lyndon_ab_len4[0], "a");
    assert_eq!(oracles.lyndon_ab_len4[7], "b");

    // 2. Stirling numbers & Bell numbers
    for entry in &oracles.stirling_second_kind {
        let got = stirling_second_kind(entry.n as u32, entry.k as u32);
        assert_eq!(
            got,
            entry.value.into(),
            "S({}, {}) mismatch",
            entry.n,
            entry.k
        );
    }
    for entry in &oracles.bell_numbers {
        let got = bell_number(entry.n as u32);
        assert_eq!(got, entry.value.into(), "B({}) mismatch", entry.n);
    }

    // 3. Riemann tensor canonicalization via Butler-Portugal rank-N
    let riemann_sym = TensorSymmetryN {
        rank: 4,
        generators: vec![
            (vec![1, 0, 2, 3], -1),
            (vec![0, 1, 3, 2], -1),
            (vec![2, 3, 0, 1], 1),
        ],
    };
    for r in &oracles.riemann_contractions {
        let perm_u8: Vec<u8> = r.perm.iter().map(|&x| x as u8).collect();
        let expected_u8: Vec<u8> = r.expected_canonical.iter().map(|&x| x as u8).collect();
        let res = ButlerPortugal::canonicalize_n(&perm_u8, &riemann_sym, &[]);
        assert_eq!(res.indices, expected_u8, "{}", r.name);
        assert_eq!(res.sign, r.expected_sign, "{}", r.name);
    }

    // 4. Transform sample sanity
    for t in &oracles.transforms {
        match t.kind.as_str() {
            "laplace" => {
                let s = t.s_sample.expect("s_sample");
                assert!(((1.0 / (s + 2.0)) - t.expected_value).abs() < 1e-12);
            }
            "z_transform" => {
                let z = t.z_sample.expect("z_sample");
                assert!(((z / (z - 0.5)) - t.expected_value).abs() < 1e-12);
            }
            "fourier" => {
                let w = t.omega_sample.expect("omega_sample");
                let val = std::f64::consts::PI.sqrt() * (-(w * w) / 4.0).exp();
                assert!((val - t.expected_value).abs() < 1e-12);
            }
            other => panic!("unexpected transform oracle kind: {other}"),
        }
    }
}
